import fs from'node:fs';import assert from'node:assert/strict';import{hash,json}from'./bounded-source-hash-20261026.mjs';
const stage='F:/VisibleMedicine/staging/20261027-course-directory',prep=json(stage+'/PREPARATION.json'),parent=json(prep.parent.path),site=prep.website;
assert.equal(hash(prep.parent.path),prep.parent.sha256);const changed=['app/studio/courses/page.tsx','tests/studio-course-search.test.mjs'],added=['lib/studio-course-directory.ts','tests/studio-course-directory.test.mjs'];
