const oldTest=fs.readFileSync(parent.website+'/'+changed[1],'utf8'),now=fs.readFileSync(site+'/'+changed[1],'utf8'),insertions=["import {getStudioCourseDirectory} from '../lib/studio-course-directory.ts';\n","    '@/lib/studio-course-directory': {getStudioCourseDirectory},\n"];let restored=now;for(const x of insertions){assert.equal(restored.split(x).length,2);restored=restored.replace(x,'');}assert.equal(restored,oldTest);fs.writeFileSync(stage+'/SEARCH_TEST_INVERSE_V3.json',JSON.stringify({path:changed[1],beforeSha256:hash(parent.website+'/'+changed[1]),afterSha256:hash(site+'/'+changed[1]),removeInsertions:insertions,allOriginalAssertionsUnchanged:true},null,2)+'\n',{flag:'wx'});
