const paths=[...parent.sourceRows.map(r=>r.path),...added];assert.equal(new Set(paths).size,paths.length);const sourceRows=paths.sort().map(p=>({path:p,bytes:fs.statSync(site+'/'+p).size,sha256:hash(site+'/'+p)}));
fs.writeFileSync(stage+'/SOURCE_CANDIDATE_V3.json',JSON.stringify({...parent,at:new Date().toISOString(),website:site,parent:prep.parent.path,parentSha256:prep.parent.sha256,sourceRows,sourcePaths:sourceRows.length,changedAuthoredPaths:changed,newPaths:added,generatedPaths:[],verification:{searchTestInverse:{path:stage+'/SEARCH_TEST_INVERSE_V3.json',sha256:hash(stage+'/SEARCH_TEST_INVERSE_V3.json')}},reviewBindingSha256:binding.sha256,installed:false,normalPreviewChanged:false},null,2)+'\n',{flag:'wx'});console.log(JSON.stringify({sourcePaths:sourceRows.length,reviewBindingUnchanged:true}));
